const Theme=require("../models/themesModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_theme=(t,h,e)=>{Theme.create(t.body).then(e=>{h.status(200).send(e)}).catch(e=>{h.status(422).send(handleErrors(e,t,"theme"))})},get_themes=(e,h,s)=>{const d=e.query.page-1||0;Theme.find({}).count().then(t=>{Theme.find({}).sort({createdAt:-1}).skip(8*d).limit(8).then(e=>h.status(200).send({themes:e,total_themes:t,per_page:8})).catch(s)})},get_admin_themes=(e,h,s)=>{const d=e.query.page-1||0;Theme.find({}).count().then(t=>{Theme.find({}).skip(30*d).limit(30).then(e=>h.status(200).send({themes:e,total_themes:t,per_page:30})).catch(s)})},get_single_theme=(e,t,h)=>{Theme.findById({_id:e.params.id}).then(e=>t.status(200).send(e)).catch(h)},update_theme=(e,t,h)=>{Theme.findByIdAndUpdate({_id:e.params.id},e.body,{new:!0}).then(e=>t.status(200).send(e)).catch(h)},delete_theme=(e,t,h)=>{Theme.findByIdAndDelete({_id:e.params.id}).then(e=>t.status(200).send(e)).catch(h)};module.exports={create_theme:create_theme,update_theme:update_theme,get_single_theme:get_single_theme,get_admin_themes:get_admin_themes,get_themes:get_themes,delete_theme:delete_theme};